// Problem 29:
// How many distinct terms are in the sequence generated by a^b for 2 ≤ a ≤ 100  and  2 ≤ b ≤ 100 ?

// We can brute force this exercice since 100*100 isn't that big for a computer.

using System.Numerics;

// Hashset only guards distinct numbers.
HashSet<BigInteger> numbers = new HashSet<BigInteger>();

for (int a = 2; a <= 100; a++)
{
    for (int b = 2; b <= 100; b++)
    {
        numbers.Add(BigInteger.Pow(a, b));
    }
}

Console.WriteLine(numbers.Count);

// Answer: 9183
